class Coin {
    private final int value;

    Coin(int value) { this.value = value; }

    @Override
    public boolean equals(Object other) {
        // true when other is a Coin (call it c) with the same value
        return other instanceof Coin c && c.value == this.value;
    }
}

Coin[] purse = { new Coin(5), new Coin(9), new Coin(5) };
Coin target = new Coin(5);
int same = 0;
int equal = 0;
for (Coin c : purse) {
    if (c == target) { same++; }
    if (c.equals(target)) { equal++; }
}
System.out.println(same + " " + equal);

